scwin.selectYear_onviewchange = function(info) {
    mapchart1.dataMapPath = "/TEST/20160425rc/mapdata/" + info.newValue;
    mapchart1.changeMapPath(mapchart1.dataMapPath);
};
scwin.mapchart1_onbeforemapchange = function(info) {
    if (info.newMapCode.length > 2) {
        return false; // 지도 확장기능 사용하지 않음 
    }
};
